import test from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import fs from 'node:fs/promises';
import {SqliteD1Database} from './sqlite-d1';
import {D1DistributionRuntime} from '../../apps/admin-worker/src/distribution-runtime';
import {ScheduleRepository} from '../../apps/admin-worker/src/substack-schedules';
import {ScheduleCoordinator,contentFingerprint,makeScheduleApproval,SCHEDULE_POLICY,type ScheduleContext,type ScheduleRequest,type ScheduleObservation,type ScheduleProvider} from './substack-schedule';
import {renderedArticle} from './substack-browser';
import type {ScheduledSource} from './scheduled-source';

const now='2026-10-19T01:00:00.000Z',at='2026-10-21T23:00:00.000Z';
const source=(version='a'):ScheduledSource=>({slug:'trial',sourcePath:'src/content/posts/trial.md',sourceCommit:version.repeat(40),sourceRevision:'sha256:'+version.repeat(64),article:{slug:'trial',sourceRevision:'sha256:'+version.repeat(64),title:'Title '+version,description:'Description '+version,canonicalUrl:'https://gcake119.github.io/gcake-dev/posts/trial/',body:`## Heading\n\nBody ${version}.\n\n[原文與最新版本](https://gcake119.github.io/gcake-dev/posts/trial/)`,assets:[]}});
const content=(s:ScheduledSource)=>({title:s.article.title,description:s.article.description,html:renderedArticle(s.article).html});
class Provider implements ScheduleProvider{
 calls:string[]=[];post?:ScheduleObservation;fail?:string;rewriteSlug=false;onRead?:()=>void;
 async find(){this.calls.push('find');return {complete:true,scanned:['published','draft','scheduled'],items:this.post?[structuredClone(this.post)]:[]};}
 async read(id:string){this.calls.push('read');this.onRead?.();assert.equal(id,this.post?.id);return structuredClone(this.post!);}
 async create(){this.calls.push('create');this.post={id:'123',slug:'',state:'draft',timeZone:'Asia/Taipei',listEvidence:{draft:true,scheduled:false},saved:true,content:{title:'',html:''}};if(this.fail==='create')throw Error('lost create');return this.post.id;}
 async update(id:string,s:ScheduledSource,published:boolean){this.calls.push(published?'update-public':'update-draft');assert.equal(id,this.post?.id);this.post!.content=content(s);this.post!.slug=this.rewriteSlug?'trial-2':s.slug;if(this.fail==='update')throw Error('lost update');}
 async arm(id:string,time:string){this.calls.push('arm');assert.equal(id,this.post?.id);Object.assign(this.post!,{state:'scheduled',listEvidence:{draft:false,scheduled:true},scheduledAt:time,timeZone:'Asia/Taipei',email:true,appInbox:true,audience:'everyone'});if(this.fail==='arm')throw Error('lost arm');}
 async remove(id:string){this.calls.push('remove');assert.equal(id,this.post?.id);if(this.fail==='remove')throw Error('lost remove');this.post!.state='draft';this.post!.listEvidence={draft:true,scheduled:false};delete this.post!.scheduledAt;}
}
async function fixture(databasePath=':memory:'){const db=new DatabaseSync(databasePath);for(const file of ['0003_publication_operations.sql','0006_distribution_checkpoints.sql','0007_substack_schedules.sql'])db.exec(await fs.readFile(new URL('../../apps/admin-worker/migrations/'+file,import.meta.url),'utf8'));const d1=new SqliteD1Database(db),repo=new ScheduleRepository(d1),provider=new Provider();let current=source(),slot={reservationId:'fixed:trial:'+at,queueVersion:1,slug:'trial',scheduledAt:at,confirmed:true};
 const context:ScheduleContext={readSource:async()=>current,readSlot:async()=>slot,readPublic:async(id:string,url:string)=>{assert.equal(id,provider.post?.id);if(provider.post?.state!=='published')throw Error('SUBSTACK_PUBLIC_HTTP_FAILED');return {...structuredClone(provider.post!),canonical:url,publishedAt:at};},now:()=>now};
 const coordinator=new ScheduleCoordinator(repo,new D1DistributionRuntime(d1),provider,context);
 const request=(operation:ScheduleRequest['operation'],extra:Partial<ScheduleRequest>={})=>{const r:ScheduleRequest={policyVersion:SCHEDULE_POLICY,scheduleId:'schedule-trial',slug:'trial',operation,source:current,slot,...extra};return {...r,approval:makeScheduleApproval(r)};};
 return {db,repo,provider,coordinator,request,context,setSource:(s:ScheduledSource)=>current=s,setSlot:(s:typeof slot)=>slot=s,close:()=>db.close()};}

test('advance same-ID prepare/arm is independent of Pages, idempotent, and delivery remains evidence not receipt',async()=>{const f=await fixture();try{
 let r=await f.coordinator.run(f.request('prepare-draft'));assert.equal(r.observedState,'draft_prepared');assert.equal(r.remoteId,'123');
 r=await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));assert.equal(r.observedState,'scheduled');assert.equal(r.observedTime,at);assert.equal(r.delivery,'armed');
 await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));assert.equal(f.provider.calls.filter(c=>c==='create').length,1);assert.equal(f.provider.calls.filter(c=>c==='arm').length,1);
 f.provider.post!.state='published';r=await f.coordinator.observe('schedule-trial',source(),{...f.request('arm-schedule').slot!},'2026-10-22T00:00:00Z');assert.equal(r.observedState,'verified');assert.equal(r.delivery,'unknown');assert.equal(r.contentVerifiedRevision,source().sourceRevision);
 }finally{f.close();}});
for(const invalid of ['legacy','unconfirmed','past','horizon','timezone'] as const)test('schedule rejects '+invalid+' before provider writes',async()=>{const f=await fixture();try{
 const r=f.request('arm-schedule');if(invalid==='legacy')r.policyVersion='pages-first-no-newsletter' as never;if(invalid==='unconfirmed')r.slot!.confirmed=false;if(invalid==='past')r.slot!.scheduledAt=now;if(invalid==='horizon')r.slot!.scheduledAt='2027-02-01T23:00:00.000Z';if(invalid==='timezone')r.timeZone='UTC';r.approval=makeScheduleApproval(r);
 await assert.rejects(f.coordinator.run(r),/SUBSTACK_/);assert.deepEqual(f.provider.calls,[]);
 }finally{f.close();}});

test('content sync actually edits drafts and public articles; no-op preserves schedules and delivered version',async()=>{const f=await fixture();try{
 await f.coordinator.run(f.request('prepare-draft'));const before=f.provider.calls.length;
 await f.coordinator.run(f.request('sync-content',{remoteId:'123'}));assert.ok(f.provider.calls.slice(before).every(c=>c==='read'));
 f.setSource(source('b'));await f.coordinator.run(f.request('sync-content',{remoteId:'123'}));assert.deepEqual(f.provider.post!.content,content(source('b')));
 await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.provider.post!.state='published';await f.coordinator.observe('schedule-trial',source('b'),f.request('arm-schedule').slot!,'2026-10-22T00:00:00Z');
 f.setSource(source('c'));await f.coordinator.run(f.request('sync-content',{remoteId:'123'}));let r=await f.repo.get('schedule-trial');assert.equal(r!.contentVerifiedRevision,source('c').sourceRevision);assert.equal(r!.deliveredRevision,source('b').sourceRevision);assert.equal(r!.remoteId,'123');assert.equal(r!.publicationMinute,at);assert.equal(f.provider.calls.filter(c=>c==='arm').length,1);
 r=await f.coordinator.observe('schedule-trial',source('c'),f.request('arm-schedule').slot!,'2026-10-22T00:00:00Z');assert.equal(r!.observedState,'verified');
 }finally{f.close();}});
test('armed revision and postponement disarm first, then edit/arm once; cancellation retains draft',async()=>{const f=await fixture();try{
 await f.coordinator.run(f.request('prepare-draft'));await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.setSource(source('b'));let start=f.provider.calls.length;
 await f.coordinator.run(f.request('revise-schedule',{remoteId:'123'}));const writes=f.provider.calls.slice(start).filter(c=>c!=='read');assert.deepEqual(writes,['remove','update-draft','arm']);
 f.setSlot({...f.request('arm-schedule').slot!,scheduledAt:'2026-10-25T23:00:00.000Z',reservationId:'fixed:replacement',queueVersion:2});start=f.provider.calls.length;
 await f.coordinator.run(f.request('postpone-schedule',{remoteId:'123'}));assert.deepEqual(f.provider.calls.slice(start).filter(c=>c!=='read'),['remove','arm']);
 let r=await f.coordinator.run(f.request('cancel-schedule',{remoteId:'123'}));assert.equal(r.observedState,'cancelled_draft');assert.equal(f.provider.post?.id,'123');assert.equal(f.provider.post?.state,'draft');await f.coordinator.run(f.request('cancel-schedule',{remoteId:'123'}));assert.equal(f.provider.calls.filter(c=>c==='create').length,1);
 }finally{f.close();}});
for(const failure of ['create','arm','remove','update'])test('unknown '+failure+' survives restart and refuses replay',async()=>{const f=await fixture();try{
 if(failure!=='create')await f.coordinator.run(f.request('prepare-draft'));if(failure==='remove')await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.provider.fail=failure;
 const op=failure==='create'?'prepare-draft':failure==='remove'?'cancel-schedule':failure==='update'?'sync-content':'arm-schedule';if(failure==='update')f.setSource(source('b'));
 await assert.rejects(f.coordinator.run(f.request(op,{...(failure==='create'?{}:{remoteId:'123'})})),/SUBSTACK_/);const calls=f.provider.calls.length;
 await assert.rejects(f.coordinator.run(f.request(op,{...(failure==='create'?{}:{remoteId:'123'})})),/RECONCILIATION/);assert.equal(f.provider.calls.length,calls);assert.ok((await f.repo.get('schedule-trial'))?.intent);
 }finally{f.close();}});
test('reconcile lost create finds original and never creates a replacement',async()=>{const f=await fixture();try{f.provider.fail='create';await assert.rejects(f.coordinator.run(f.request('prepare-draft')));f.provider.fail=undefined;f.provider.post!.slug='trial';f.provider.post!.content=content(source());let r=await f.coordinator.run(f.request('reconcile-schedule'));assert.equal(r.remoteId,'123');assert.equal(r.intent,undefined);assert.equal(f.provider.calls.filter(c=>c==='create').length,1);}finally{f.close();}});
test('slug mismatch blocks arming; public adoption cannot backfill delivery',async()=>{const f=await fixture();try{f.provider.rewriteSlug=true;await assert.rejects(f.coordinator.run(f.request('prepare-draft')),/SLUG/);assert.equal(f.provider.calls.includes('arm'),false);}finally{f.close();}const g=await fixture();try{g.provider.post={id:'789',slug:'trial',state:'published',saved:true,content:content(source()),publishedAt:at,canonical:'https://gcakedev.substack.com/p/trial'};const r=await g.coordinator.run(g.request('prepare-draft'));assert.equal(r.remoteId,'789');await assert.rejects(g.coordinator.run(g.request('arm-schedule',{remoteId:'789'})),/TOO_LATE/);assert.ok(!g.provider.calls.includes('arm'));}finally{g.close();}});
test('published cancellation is too late and source/remote races never claim current synchronization',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.provider.post!.state='published';await assert.rejects(f.coordinator.run(f.request('cancel-schedule',{remoteId:'123'})),/TOO_LATE/);f.setSource(source('b'));const r=f.request('sync-content',{remoteId:'123'});f.provider.onRead=()=>f.setSource(source('c'));await assert.rejects(f.coordinator.run(r),/SOURCE_CHANGED/);assert.equal(f.provider.calls.includes('update-public'),false);}finally{f.close();}});
test('background drift never accesses authenticated provider and preserves last armed time',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));const n=f.provider.calls.length;let r=await f.coordinator.observe('schedule-trial',source('b'),f.request('arm-schedule').slot!,now);assert.equal(r.pendingAction,'sync-content');assert.equal(r.observedTime,at);assert.equal(f.provider.calls.length,n);r=await f.coordinator.observe('schedule-trial',undefined,undefined,now);assert.equal(r.pendingAction,'cancel-schedule');assert.equal(r.observedTime,at);assert.equal(f.provider.calls.length,n);}finally{f.close();}});
test('semantic content comparison retains headings, links, code whitespace and image alt',()=>{assert.notEqual(contentFingerprint({title:'X',html:'<h2>Hello</h2>'}),contentFingerprint({title:'X',html:'<p>Hello</p>'}));assert.equal(contentFingerprint({title:'X',html:'<p> Hello   world </p>'}),contentFingerprint({title:'X',html:'<div><p>Hello world</p></div>'}));for(const [a,b]of [['<pre>a  b</pre>','<pre>a b</pre>'],['<a href="https://example.com/a">A</a>','<a href="https://example.com/b">A</a>'],['<img src="https://example.com/a" alt="A">','<img src="https://example.com/a" alt="B">']])assert.notEqual(contentFingerprint({title:'X',html:a}),contentFingerprint({title:'X',html:b}));});
test('occupied discovery is never adopted or overwritten',async()=>{const f=await fixture();try{f.provider.post={id:'789',slug:'someone-else',state:'draft',saved:true,content:{title:'Other',html:'<p>Other</p>'}};await assert.rejects(f.coordinator.run(f.request('prepare-draft')),/IDENTITY|SLUG/);assert.equal(f.provider.calls.includes('update-draft'),false);assert.equal((await f.repo.get('schedule-trial'))?.remoteId,undefined);}finally{f.close();}});
test('lost arm reconciles the original commitment and delivery revision without replay',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));f.provider.fail='arm';await assert.rejects(f.coordinator.run(f.request('arm-schedule',{remoteId:'123'})));f.provider.fail=undefined;const r=await f.coordinator.run(f.request('reconcile-schedule',{remoteId:'123'}));assert.equal(r.delivery,'armed');assert.equal(r.armedRevision,source().sourceRevision);assert.equal(r.slot?.scheduledAt,at);assert.equal(f.provider.calls.filter(c=>c==='arm').length,1);}finally{f.close();}});
test('sending content cannot be edited or mistaken for a completed public correction',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));f.provider.post!.state='sending';f.setSource(source('b'));await assert.rejects(f.coordinator.run(f.request('sync-content',{remoteId:'123'})),/TOO_LATE/);assert.equal(f.provider.calls.includes('update-public'),false);}finally{f.close();}});
test('independent writers and stale generations cannot replace an existing intent',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));const old=(await f.repo.get('schedule-trial'))!;await f.repo.save({...old,pendingAction:'cancel-schedule'},old.version);await assert.rejects(f.repo.save({...old,pendingAction:'sync-content'},old.version),/CONFLICT/);const runtime=new D1DistributionRuntime(new SqliteD1Database(f.db));await runtime.acquire('trial','substack','other-owner',now);const n=f.provider.calls.length;await assert.rejects(f.coordinator.run(f.request('arm-schedule',{remoteId:'123'})),/LOCKED/);assert.equal(f.provider.calls.length,n);}finally{f.close();}});
test('source slug rename maps the original ID and never creates a replacement',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));const renamed=source('b');renamed.slug='renamed';renamed.article.slug='renamed';f.setSource(renamed);await assert.rejects(f.coordinator.run(f.request('sync-content',{slug:'renamed',remoteId:'123'})),/RENAME/);const r=await f.coordinator.run(f.request('sync-content',{slug:'renamed',remoteId:'123',previousSlug:'trial'}));assert.equal(r.remoteId,'123');assert.equal(r.slug,'renamed');assert.deepEqual(r.previousSlugs,['trial']);assert.equal(f.provider.calls.filter(c=>c==='create').length,1);}finally{f.close();}});
test('image readback must demonstrate every image loaded before any arm',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));f.provider.post!.content.html+='<img src="https://example.com/a.png" alt="A">';await assert.rejects(f.coordinator.run(f.request('arm-schedule',{remoteId:'123'})),/EVIDENCE/);assert.equal(f.provider.calls.includes('arm'),false);}finally{f.close();}});
test('legacy coordinator cannot adopt a new-policy schedule or its former slug',async()=>{const {D1PublicationRepository}=await import('../../apps/admin-worker/src/publication-operations');const {DistributionCoordinator}=await import('../../apps/admin-worker/src/distribution-coordinator');const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));const coordinator=new DistributionCoordinator(new D1PublicationRepository(new SqliteD1Database(f.db)),undefined);await assert.rejects(coordinator.run({...source().article,publishedAt:'2026-10-01'},'substack','verify'),/SCHEDULE_OWNED/);assert.deepEqual(await new D1PublicationRepository(new SqliteD1Database(f.db)).listStates('trial'),[]);}finally{f.close();}});
test('confirmed queue adapter uses confirmed overrides, never estimates or paused commitments',async()=>{const {scheduledRuntime}=await import('./scheduled-runtime');const f=await fixture();try{f.db.exec("CREATE TABLE release_queue_runtime (id INTEGER PRIMARY KEY,version INTEGER,document TEXT)");f.db.prepare('INSERT INTO release_queue_runtime VALUES (1,7,?)').run(JSON.stringify({overrides:{trial:'2026-10-22T07:00:00+08:00'},paused:[],releases:[]}));const ports=scheduledRuntime(new SqliteD1Database(f.db),{} as never);const slot=(await ports.readSlot('trial'))!;assert.equal(slot.queueVersion,7);assert.equal(new Date(slot.scheduledAt).toISOString(),at);assert.equal(await ports.readSlot('estimated'),undefined);f.db.prepare('UPDATE release_queue_runtime SET document=?').run(JSON.stringify({overrides:{trial:slot.scheduledAt},paused:['post:trial']}));assert.equal(await ports.readSlot('trial'),undefined);}finally{f.close();}});
test('foreground handoff refuses stale generation, intent, version and wrong delivery evidence',async()=>{const {validateScheduleHandoff}=await import('./substack-schedule-handoff');const {validateScheduleReply}=await import('./substack-schedule-attended');const {createHash}=await import('node:crypto');const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));let state=(await f.repo.get('schedule-trial'))!;state=await f.repo.save({...state,intent:{id:'one-arm',action:'arm',scheduledAt:at,slot:f.request('arm-schedule').slot,sourceRevision:source().sourceRevision,createdAt:now}},state.version);const request={exchangeVersion:2,policyVersion:SCHEDULE_POLICY,scheduleId:state.scheduleId,sourceCommit:source().sourceCommit,article:source().article,operation:'arm-schedule',action:'schedule-arm',remote:{id:'123',url:'https://gcakedev.substack.com/publish/post/123'},delivery:{email:true,appInbox:true},audience:'everyone',timeZone:'Asia/Taipei',intentId:'one-arm',recordVersion:state.version,scheduledAt:at,slot:f.request('arm-schedule').slot} as const;
 const envelope={version:2,requestId:'unique',slug:'trial',sourceRevision:source().sourceRevision,operation:request.operation,action:request.action,remoteId:'123',expiresAt:Date.now()+60000,scopeDigest:createHash('sha256').update(JSON.stringify(request)).digest('hex'),request} as const;
 validateScheduleHandoff(envelope,state,source(),Date.parse(now),f.request('arm-schedule').slot);for(const patch of [{version:state.version+1},{intent:{...state.intent!,id:'other'}},{slug:'other'}])assert.throws(()=>validateScheduleHandoff(envelope,{...state,...patch},source()));
 const reply={...f.provider.post!,state:'scheduled',listEvidence:{draft:false,scheduled:true},scheduledAt:at,timeZone:'Asia/Taipei',email:true,appInbox:true,audience:'everyone'} as const;validateScheduleReply(request,reply);assert.throws(()=>validateScheduleReply(request,{...reply,appInbox:false}),/EVIDENCE/);assert.throws(()=>validateScheduleReply(request,{...reply,scheduledAt:'2026-10-21T22:00:00Z'}),/EVIDENCE/);
 }finally{f.close();}});
test('real CLI review executes through durable attended intents and rejects a legacy approval',async()=>{const {runScheduledDistribution}=await import('./run-scheduled-distribution');const os=await import('node:os');const path=await import('node:path');const f=await fixture(),directory=await fs.mkdtemp(path.join(os.tmpdir(),'substack-cli-'));try{
 f.db.exec('CREATE TABLE release_queue_runtime (id INTEGER PRIMARY KEY,version INTEGER,document TEXT)');f.db.prepare('INSERT INTO release_queue_runtime VALUES (1,1,?)').run(JSON.stringify({overrides:{},paused:[],releases:[]}));
 const config=path.join(directory,'config.json'),receipt=path.join(directory,'review.json'),approval=path.join(directory,'approval.json');await fs.writeFile(config,JSON.stringify({scheduled:{policyVersion:SCHEDULE_POLICY,writeEnabled:true,transport:'attended',sessionDirectory:directory},substack:{ui:{origin:'https://gcakedev.substack.com'}}}));
 const actions:string[]=[];const deps={readSource:async()=>source(),assertMain:async()=>{},exchange:async(r:import('./substack-schedule-attended').ScheduleExchangeRequest)=>{actions.push(r.action);if(r.action==='schedule-find')return f.provider.find();if(r.action==='schedule-create')return {id:await f.provider.create()};if(r.action==='schedule-update'){await f.provider.update(r.remote!.id,source(),false);return f.provider.read(r.remote!.id);}if(r.action==='schedule-read')return f.provider.read(r.remote!.id);throw Error('unexpected operation');}};
 const args=['prepare-draft','trial','substack','--config',config];await runScheduledDistribution([...args,'--out',receipt],process.cwd(),new SqliteD1Database(f.db),deps);const review=JSON.parse(await fs.readFile(receipt,'utf8'));await fs.writeFile(approval,JSON.stringify({approved:true,newsletter:'skip'}));await assert.rejects(runScheduledDistribution([...args,'--execute','--receipt',receipt,'--approval',approval],process.cwd(),new SqliteD1Database(f.db),deps),/APPROVAL/);assert.deepEqual(actions,[]);
 await fs.writeFile(approval,JSON.stringify({...review.approvalTemplate,approved:true}));const r=await runScheduledDistribution([...args,'--execute','--receipt',receipt,'--approval',approval],process.cwd(),new SqliteD1Database(f.db),deps);assert.equal(r?.remoteId,'123');assert.equal(r?.observedState,'draft_prepared');assert.deepEqual(actions,['schedule-find','schedule-create','schedule-read','schedule-read','schedule-update','schedule-read']);assert.equal((await f.repo.get('substack:trial'))?.intent,undefined);
 }finally{f.close();await fs.rm(directory,{recursive:true,force:true});}});
test('public provider-only divergence is corrected despite unchanged source; equal content does not write',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.provider.post!.state='published';f.provider.post!.publishedAt=at;await f.coordinator.observe('schedule-trial',source(),f.request('arm-schedule').slot!,'2026-10-22T00:00:00Z');let n=f.provider.calls.length;await f.coordinator.run(f.request('sync-content',{remoteId:'123'}));assert.equal(f.provider.calls.slice(n).filter(c=>c!=='read').length,0);f.provider.post!.content.html='<p>Platform-only edit</p>';n=f.provider.calls.length;const r=await f.coordinator.run(f.request('sync-content',{remoteId:'123'}));assert.equal(r.contentVerifiedRevision,source().sourceRevision);assert.deepEqual(f.provider.calls.slice(n).filter(c=>c!=='read'),['update-public']);assert.equal(r.publicationMinute,at);}finally{f.close();}});
test('foreground verification never replaces the armed minute with a divergent public date',async()=>{const f=await fixture();try{await f.coordinator.run(f.request('prepare-draft'));await f.coordinator.run(f.request('arm-schedule',{remoteId:'123'}));f.provider.post!.state='published';f.provider.post!.publishedAt='2026-10-22T00:00:00.000Z';f.context.readPublic=async(_id,url)=>({...f.provider.post!,canonical:url,publishedAt:f.provider.post!.publishedAt!});await assert.rejects(f.coordinator.run(f.request('sync-content',{remoteId:'123'})),/PUBLIC_EVIDENCE/);assert.notEqual((await f.repo.get('schedule-trial'))?.observedState,'verified');}finally{f.close();}});
