  const reviewed=f.request('arm-schedule',{remoteId:'123'});f.setSlot(current);await assert.rejects(f.coordinator.run(reviewed),/SUBSTACK_SCHEDULE_SLOT_UNCONFIRMED/);assert.equal(f.provider.calls.length,n);
